Opción (s/n): s
Sí

$ cat hola.sh
#!/usr/bin/env bash
saludar() {
    echo "Hola $1"
}

sumar() {
    local total=$(($1 + $2))
    echo $total
}

saludar "Ana"
resultado=$(sumar 4 5)
echo "Resultado: $resultado"
$ bash hola.sh
Hola Ana
Resultado: 9
